"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1115],{61155:t=>{t.exports=JSON.parse('{"functions":[{"name":"CreateCharacterWeld","desc":"Builds the constraint joining `part1` to `part0`.\\n\\nEither attachment may be omitted. A missing attachment is created on its part at\\na CFrame that preserves the parts\' current world poses, so applying the returned\\nconstraint will not snap them together.\\n\\nThe constraint is named `Weld_<part0>_<part1>` but is **not** parented \u2014 the\\ncaller decides where it lives and is responsible for destroying it.\\n\\n```lua\\nlocal constraint = CreateCharacterWeld({\\n\\tpart0 = character.RightHand,\\n\\tpart1 = tool.Handle,\\n})\\nconstraint.Parent = tool.Handle\\n```","params":[{"name":"data","desc":"","lua_type":"{ part0: BasePart, part1: BasePart, attachment0: Attachment?, attachment1: Attachment? }"}],"returns":[{"desc":"","lua_type":"AnimationConstraint"}],"function_type":"static","source":{"line":39,"path":"src/Shared/Modules/CreateCharacterWeld.luau"}}],"properties":[],"types":[],"name":"CreateCharacterWeld","desc":"Joins two parts with an [AnimationConstraint], the joint type used by\\nAvatarJointUpgrade rigs.\\n\\nThe Roblox-default R15 character no longer uses [Motor6D]s, so tools and\\naccessories attached to a modern character need a constraint rather than the\\nMotor6D that [CreateWeld] produces.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":14,"path":"src/Shared/Modules/CreateCharacterWeld.luau"}}')}}]);